using System.IO;
using System.Text.Json;
using System.Diagnostics;
using Microsoft.Extensions.DependencyInjection;
using ClosedXML.Excel;
namespace AccurateHireIQ;
public static class SelfTest
{
 public static async Task Run(IServiceProvider services)
 {
  var store=services.GetRequiredService<Store>();var importer=services.GetRequiredService<ImportService>();var results=new List<object>();var folder=store.Root;var watch=Stopwatch.StartNew();
  void Assert(bool condition,string name){if(!condition)throw new Exception("TEST FAILED: "+name);results.Add(new{name,passed=true});}
  try{
   var sample=Path.Combine(AppContext.BaseDirectory,"Data","Check-only-sample.xlsx");var preview=importer.Preview(sample);long n=await Task.Run(()=>importer.Import(sample,ImportService.Guess(preview.Headers),preview.Sheet,null,CancellationToken.None));
   Assert(n==1000,"Supplied sample imports all 1,000 records");Assert(store.Count(new("PASS"))==700&&store.Count(new("REVIEW"))==100&&store.Count(new("STOP"))==200&&store.Count(new("UNCLASSIFIED"))==0,"Supplied sample classified as 700 PASS / 100 REVIEW / 200 REJECT (STOP) / 0 UNCLASSIFIED");Assert(store.Headers().Count==56,"All 56 original columns retained");Assert(store.Count(new(Finding:"Missing ID"))==1000,"Missing source IDs flagged without fabricated candidate IDs");
   Assert(preview.Headers.Count(ImportService.IsCheck)==50,"All 50 sample screening columns recognized; six personal fields excluded");
   string Roll(params string[] values){var fields=new Dictionary<string,string>{{"Full Name","Stop Review"},{"Gender","Unknown"},{"State","REVIEW"},{"Marital Status","Unknown"}};for(int i=0;i<values.Length;i++)fields[$"Check {i+1}"]=values[i];return ScreeningClassifier.Evaluate(fields,ImportService.Guess(fields.Keys.ToList())).Status;}
   Assert(Roll("Pass"," PASS ","pass")=="PASS","All-Pass is case-insensitive and trimmed; personal fields do not influence classification");
   Assert(Roll("Review: follow-up","Hard Stop: source flag","Pass")=="STOP"&&Roll("Stop","Review")=="STOP"&&Roll("Rejected","Pass")=="STOP","STOP / Hard Stop / Reject dominate REVIEW and PASS");
   Assert(Roll("Pass","review: source issue")=="REVIEW","Explicit Review dominates Pass");
   Assert(Roll("Pass","")=="REVIEW"&&Roll("Pass","See finding 99")=="REVIEW"&&Roll("Pass","Unknown")=="REVIEW","Blank, unknown and unresolved-reference checks cannot silently pass");
   Assert(Roll("No stop found","Pass")=="REVIEW"&&Roll("Stop cleared","Pass")=="REVIEW"&&Roll("Review completed","Pass")=="REVIEW"&&Roll("stopwatch","Pass")=="REVIEW","No substring-based false STOP or false PASS");
   Assert(Roll()=="UNCLASSIFIED","No screening columns remains unclassified");
   foreach(var category in new[]{"PASS","REVIEW","STOP"}){var path=Path.Combine(folder,$"sample-{category}.xlsx");var count=importer.Export(path,new(category),null,CancellationToken.None);using var wb=new XLWorkbook(path);var ws=wb.Worksheet(1);Assert(count==store.Count(new(category))&&ws.LastRowUsed()!.RowNumber()==count+1&&ws.Cell(2,57).GetString()==(category=="STOP"?"REJECT (STOP)":category),$"Sample {category} export has exact full-category rows and computed classification");}
   var originalRow=store.Query(new(),0,1)[0];Assert(store.ClassificationFor(originalRow.RowId)!.Evidence.Count==50,"PASS classification traces to all 50 source check values");
   using(var c=store.Open()){using var q=c.CreateCommand();q.CommandText="UPDATE Candidates SET Status='UNCLASSIFIED'; DELETE FROM Classifications;";q.ExecuteNonQuery();}
   Assert(importer.UpgradeExisting()==1000&&store.Count(new("PASS"))==700&&store.Count(new("REVIEW"))==100&&store.Count(new("STOP"))==200,"Legacy imported sample automatically reclassified without re-upload");
   Assert(importer.UpgradeExisting()==0&&store.Query(new(),0,1)[0].OriginalJson==originalRow.OriginalJson&&store.Count(new())==1000,"Migration is idempotent; original source values and rows unchanged");
   var latest=Path.Combine(AppContext.BaseDirectory,"Data","Sample.xlsx");var latestPreview=importer.Preview(latest);var latestMap=ImportService.Guess(latestPreview.Headers);Assert(latestMap.Status=="Final","Final column automatically mapped as authoritative overall result");importer.Import(latest,latestMap,latestPreview.Sheet,null,CancellationToken.None);Assert(store.Count(new("PASS"))==700&&store.Count(new("REVIEW"))==129&&store.Count(new("STOP"))==171,"Latest Final column preserved: 700 PASS / 129 REVIEW / 171 STOP");Assert(store.Count(new(Finding:"Conflicting fields"))==29,"29 Final REVIEW vs explicit Hard Stop discrepancies flagged without overwriting Final");
   var csv=Path.Combine(folder,"cases.csv");File.WriteAllText(csv,"Candidate ID,Candidate Name,Overall Screening Result,Job Role,Location,License Verification,Remarks\nA1,Alice, pass ,Driver,GA,Pending,=1+1\nA1,Bob,REVIEW,Driver,GA,,source note\nB2,Charlie,stop,Warehouse,IL,Pass,plain\n,Dana,Unknown,Driver,IL,Pass,plain\nC3,Eve,,Warehouse,GA,Pass,plain\n");
   var p=importer.Preview(csv);n=importer.Import(csv,ImportService.Guess(p.Headers),p.Sheet,null,CancellationToken.None);Assert(n==5,"All fixture rows retained");Assert(store.Count(new("PASS"))==1&&store.Count(new("REVIEW"))==1&&store.Count(new("STOP"))==1&&store.Count(new("UNCLASSIFIED"))==2,"Trimmed case-insensitive classification and unknown-status handling");Assert(store.Count(new(Finding:"Duplicate ID"))==2,"Both duplicate ID rows retained and flagged");Assert(store.Count(new(Finding:"Conflicting fields"))==1,"Explicit PASS/pending contradiction flagged");Assert(store.Count(new(Status:"REVIEW",Role:"Driver",Location:"GA"))==1,"Combined filters produce exact counts");Assert(store.Count(new(Search:"' OR 1=1 --"))==0,"Search SQL injection text treated literally");Assert(store.Query(new(),1,2).Count==2,"Database pagination");
   var outFile=Path.Combine(folder,"filtered.xlsx");long exported=importer.Export(outFile,new(Status:"PASS"),null,CancellationToken.None);using(var wb=new XLWorkbook(outFile)){var s=wb.Worksheet(1);Assert(exported==1&&s.LastRowUsed()!.RowNumber()==2,"XLSX export count equals full filtered result");Assert(!s.Cell(2,7).HasFormula&&s.Cell(2,7).GetString()=="=1+1"&&s.Cell(2,7).Style.IncludeQuotePrefix,"Formula injection escaped in XLSX");}
   var csvOut=Path.Combine(folder,"all.csv");importer.Export(csvOut,new(),null,CancellationToken.None);Assert(File.ReadAllText(csvOut).Contains("'=1+1"),"CSV formula injection escaped");
   long before=store.ActiveBatch;int batches=store.History().Count;using(var cancelled=new CancellationTokenSource()){cancelled.Cancel();try{importer.Import(csv,ImportService.Guess(p.Headers),p.Sheet,null,cancelled.Token);}catch(OperationCanceledException){}}Assert(store.History().Count==batches&&store.ActiveBatch==before,"Cancelled import rolls back atomically");
   var original=store.ReadSettings();var disabled=store.ReadSettings();disabled.AllowExports=false;store.SaveSettings(disabled);bool blocked=false;try{importer.Export(Path.Combine(folder,"blocked.csv"),new(),null,CancellationToken.None);}catch(InvalidOperationException){blocked=true;}store.SaveSettings(original);Assert(blocked,"Export restriction enforced in service layer");
   Assert(AgentService.Unprotect(AgentService.Protect("test-secret"))=="test-secret","API key Windows encryption roundtrip");
   Assert(store.Count(new(SourceColumn:"License Verification",SourceText:"pending"))==1,"Exact source-column and text filter");
   await AgentIntegrationTest.Run(store,services.GetRequiredService<AgentService>());Assert(true,"Agent Framework provider-to-tool-to-response integration with local protocol fixture");
   var demo=Path.Combine(folder,"Demo-10000.xlsx");DemoData.Generate(demo);var dp=importer.Preview(demo);importer.Import(demo,ImportService.Guess(dp.Headers),dp.Sheet,null,CancellationToken.None);Assert(store.Count(new("PASS"))==7500&&store.Count(new("REVIEW"))==2000&&store.Count(new("STOP"))==500,"10,000-row synthetic demo has exact 7500/2000/500 source counts");
   var large=Path.Combine(folder,"100k.csv");using(var writer=new StreamWriter(large)){writer.WriteLine("Candidate ID,Candidate Name,Overall Screening Result,Job Role,Location,License Verification");for(int i=0;i<100000;i++)writer.WriteLine($"S{i},Synthetic Person {i},{(i%10<7?"PASS":i%10<9?"REVIEW":"STOP")},Driver,GA,Pass");}
   var perf=Stopwatch.StartNew();var lp=importer.Preview(large);importer.Import(large,ImportService.Guess(lp.Headers),lp.Sheet,null,CancellationToken.None);Assert(store.Count(new())==100000&&store.Count(new("REVIEW"))==20000,"100,000-record streaming import and aggregation");Assert(store.Query(new("REVIEW"),19950,50).Count==50,"Last page of 20,000 REVIEW records");long report=importer.Export(Path.Combine(folder,"review-20k.csv"),new("REVIEW"),null,CancellationToken.None);Assert(report==20000&&File.ReadLines(Path.Combine(folder,"review-20k.csv")).Count()==20001,"Large filtered export includes all pages");results.Add(new{name="100k import/query/export timing",seconds=perf.Elapsed.TotalSeconds});
   File.WriteAllText(Path.Combine(folder,"verification.json"),JsonSerializer.Serialize(new{success=true,elapsedSeconds=watch.Elapsed.TotalSeconds,results},new JsonSerializerOptions{WriteIndented=true}));
  }catch(Exception e){File.WriteAllText(Path.Combine(folder,"verification.json"),JsonSerializer.Serialize(new{success=false,error=e.ToString(),results},new JsonSerializerOptions{WriteIndented=true}));throw;}
 }
}
